Method.Implementation:
	#Dim %EmailRequest As mail.MailRequest
	If '$Data(%EmailRequest) Set %EmailRequest = ##class(mail.MailRequest).%New()
	If '$IsObject(%EmailRequest) Set %EmailRequest = ##class(mail.MailRequest).%New()
	Set $ZT = "EXCEPTION"
	Set pResponse = ""
	Set tDataDone = 0
	Set tLine = ""
	Set tSC=$$$OK
	Do {
		Set tLine = pInput.StringValue
			if tLine["EHLO",$i(^txt) set %lin=0
		    set ^txt(^txt,$i(%lin))=tLine
		Do {
			Set uLine = $ZCONVERT($Get(tLine),"U")
			Set tMailDomain = ..MailDomain
			Set pResponse = $$$MailDomain($$$MMResponseDefault,tMailDomain)

			If (%DataStarted > 0) {
				If (uLine = ".") {
					Set tDataDone = 1
					Set %DataStarted = 0
					Set pResponse = $$$MailDomain($$$MMResponseDataAcpt,tMailDomain)
				} Else {
					Set pResponse = ""
					If (%DataStarted > 1) {
						Set tStream = %EmailRequest.StreamGet()
						If '$IsObject(tStream) Set tStream = ##class(%GlobalCharacterStream).%New()
						Set tSC = tStream.Write(tLine_$$$terminator)
						Set tSC = %EmailRequest.StreamSet(tStream)
					}
					Else {
						If (uLine = "") {
							Set %DataStarted = 2  // Ready to Write to Stream
						} Else {
							If ($Extract(uLine,1,11) = "MESSAGE-ID:") {
								Set %EmailRequest.SenderMessageID = $Extract(tLine,12,*)
							}
							If ($Extract(uLine,1,8) = "SUBJECT:") {
								Set %EmailRequest.Subject = $Extract(tLine,9,*)
							}
						}
					}
					Set pResponse = ""
					Quit
				}
				Quit
			}

			If ($Piece(uLine,$$$Space,1) = "DATA") {
				Set %DataStarted=1
				Set pResponse = $$$MailDomain($$$MMResponseData,tMailDomain)
			}

			If $Piece(uLine,$$$Space,1) = "HELO" {
				Set pResponse = $$$MailDomain($$$MMResponseHELO,tMailDomain)
			}
			If $Piece(uLine,$$$Space,1) = "NOOP" {
				Set pResponse = $$$MailDomain($$$MMResponseDefault,tMailDomain)
			}
			If $Piece(uLine,$$$Space,1) = "MAIL" {
				Set %EmailRequest.MessageID = ##class(mail.Util).GenerateMessageID(tMailDomain)
				Set pResponse = "250 OK "_##class(mail.Util).GetFormattedMessageID(%EmailRequest.MessageID,tMailDomain)
			}
			If $Piece(uLine,$$$Space,1) = "RCPT" {
				// There may not be a space after TO:
				If $Extract(uLine,6,8) = "TO:" {
					Set tTo = $Extract(uLine,9,*)
					Set pResponse = "250 'RCPT' accepted"
				}
			}
			If $Piece(uLine,$$$Space,1) = "RSET" {
				Set pResponse = "250"
			}
			If $Piece(uLine,$$$Space,1) = "SUBJECT:" {
				Set %EmailRequest.Subject = $Extract(tLine,9,*)
				Set pResponse = $$$MailDomain($$$MMResponseDefault,tMailDomain)
			}
			If $Piece(uLine,$$$Space,1) = "TURN" {
				Set pResponse = $$$MailDomain($$$MMResponseTURN,tMailDomain)
			}
			If $Piece(uLine,$$$Space,1) = "QUIT" {
				Set pResponse = $$$MailDomain($$$MMResponseQUIT,tMailDomain)
			}
		} While (0)
		Set pOutput = ##class(Ens.StringContainer).%New(pResponse)
	} While (0)
EXIT
	If (tDataDone = 0) {
		Quit tSC
	}
	// check stream size ?
	Set tMessageID = %EmailRequest.MessageID
	$$$SyncCommitSet(tSyncCommit)
	For iTarget=1:1:$L(..TargetConfigNames, ",") { Set tOneTarget=$ZStrip($P(..TargetConfigNames,",",iTarget),"<>W")  Continue:""=tOneTarget
		Set tSC1=..SendRequestAsync(tOneTarget,%EmailRequest)  Set:$$$ISERR(tSC1) tSC=$$$ADDSC(tSC,tSC1)
	}
	$$$SyncCommitClear(tSyncCommit)
	KILL %EmailRequest
	Quit tSC
EXCEPTION
	Set $ZT = ""
	Set tSC = $$$EnsSystemError
	Goto EXIT

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}

	Set %DataStarted = 0
	Set %EmailRequest = ""
	Quit:$G($$$EnsJobLocal("TCPIn.OutsideJob")) $$$OK ; do nothing if SOAP CSP job
	Set tSC=##super()  Quit:$$$ISERR(tSC) tSC
	Set ..OldIO=$IO  Do ##class(Ens.Util.Trace).SetTraceDevice(..OldIO)
	Set ..LocalInterface=$ZStrip($P(..LocalInterface,"("),"*W")
	If 0=..BusinessHost.%GetParameter("LOGCONNECTIONS") Set ..%logConnections=0
	Do $ZU(68,57,1) ; turn on PSW2NOTHROTTLE bit to bypass throttle
	Set:..StayConnected>0 ..KeepaliveInterval=..StayConnected
	
	#; $ZU(53) means it's a tcp spawned job
	Set tDevice = $ZU(53)
	If ""'=tDevice {
		#; initialize for spawned TCP job (only possible in normal listen-for-connection mode)
		#; Job Per Connection Setting = 1
		Set ..Device = tDevice
		If ""=..SSLConfig {
			Use tDevice:(::..#Mode_"-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:0:/TCPNOXY)
		} Else {
			Use tDevice:(::..#Mode_"-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:0:/TCPNOXY:/SSL=..SSLConfig)
		}
		Do SetIO^%NLS("RAW") ; turn off translation mode
		Set tRemote=$zu(111,0), ps=$S($L(tRemote)>6:"|",1:":"), tRemote=$$$IPBinaryToText($E(tRemote,1,*-2))_ps_$ZWAscii($Reverse($E(tRemote,*-1,*)))
		Set ..IOAddr=..Port_"<-"_tRemote_$S(""=..SSLConfig:"",1:"/SSL="_..SSLConfig), ..Connected=1
		
		Set tSC = ..WriteLine($$$MailDomain($$$MMReady,..BusinessHost.MailDomain))
		Use ..OldIO
		Set:'$IsObject(..Socket) ..Socket=..SocketNewObject()
		Do ..Socket.Attach(..Device)
		Set:""'=..Terminators ..Socket.LineTerminator=..Terminators
		Set $ZT="OnConnectTrap"
		Set tSC=..BusinessHost.OnConnect(0)  If $$$ISERR(tSC) Do ..Disconnect()  Quit tSC
OnConnectTrap
	} Else {
		#; initialize for main TCP listener job
		#; Job Per Connection Setting = 0
		If "!"'=$E(..AllowedIPAddresses) { ; normal listen-for-connection mode
			Set ..%PoolLimit=$$$ConfigPoolSize(..BusinessHost.%ConfigName)  Kill ^CacheTemp.EnsTCPJobs($Job)
			Set ..%outIPAddr=""
			Set ..Device="|TCP|"_..Port
			If ..QSize>0 {
				If ""=..SSLConfig {
					Open ..Device:(:..Port:..#Mode_"A-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:..QSize:/TCPNOXY:/BINDTO=..LocalInterface):..#OpenTimeout  Set tOpenFailed='$Test
				} Else {
					Open ..Device:(:..Port:..#Mode_"A-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:..QSize:/TCPNOXY:/BINDTO=..LocalInterface:/SSL=..SSLConfig):..#OpenTimeout  Set tOpenFailed='$Test
				}
			} Else {
				If ""=..SSLConfig {
					Open ..Device:(:..Port:..#Mode_"A-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:1:/CLOSELISTEN:/TCPNOXY:/BINDTO=..LocalInterface):..#OpenTimeout  Set tOpenFailed='$Test
				} Else {
					Open ..Device:(:..Port:..#Mode_"A-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:1:/CLOSELISTEN:/TCPNOXY:/BINDTO=..LocalInterface:/SSL=..SSLConfig):..#OpenTimeout  Set tOpenFailed='$Test
				}
			}
			If tOpenFailed {
				Set tDevice=..Device, ..Device=""
				Quit $$$EnsError($$$EnsErrTCPListen,..Port,..#OpenTimeout,"Open """_tDevice_""":(:"_..Port_":"""_..#Mode_"A-D"_""":"_..Terminators_":"_..#InputBufferSize_":"_..#OutputBufferSize_":"_$S(..QSize>0:..QSize,1:"1:/CLOSELISTEN")_":/TCPNOXY:"_$S(""=..SSLConfig:"",1:"/SSL="_..SSLConfig)_"):"_..#OpenTimeout)
			}
			Use ..Device
			Do SetIO^%NLS("RAW") ; turn off translation mode
			Use ..OldIO
		} Else { ; If in connect-and-read mode
			Set tAddr=$P($E(..AllowedIPAddresses,2,*),","), ps=$S($L(tAddr,":")<=2:":",1:"|"), tPort=$P(tAddr,ps,2)
			Set ..%outIPAddr=$P(tAddr,ps)  Set:""'=tPort ..Port=tPort
			If ..StayConnected {
				Set tSC=..ConnectOut(..CallInterval)
				If $$$ISERR(tSC) {
					Set tTxt=$$$StatusDisplayString(tSC)
					$$$LOGWARNING(tTxt)
					Set ..%warnedConnect=tTxt // timeout is not fatal at this point, but do log it
				}
			}
		}
		If ..StayConnected>=0 Set ..BusinessHost.%LastReportedError=$$$StatusDisplayString($$$ERROR($$$EnsErrGeneral,"No Connection made "_$S(""'=..%outIPAddr:"to "_..%outIPAddr_$S(..%outIPAddr[":":"|",1:":"), 1:"on port ")_..Port_" within interval "_..CallInterval)) ; Prime %LastReportedError so it doesn't alert the first time if no connection arrives provided connection not required
	}
	Quit $$$OK

	If ""'=$ZU(53) {
		Set tSC=$$$OK, $ZT="ChildTrap"
		Use ..Device
		Set $ZT="OCTrap"
		Set tSC=..OnConnected()
		Set $ZT="ChildTrap"
		If '..StayConnected||$$$ISERR(tSC) { Do ..Disconnect() }
		Else { Do ..TestConnection() }
		If '..Connected {
			Set ..BusinessHost.%QuitTask=1
			Set tTxt="Closing TCP Connection Job"
			If ..%logConnections {
				$$$LOGINFO(tTxt)
			}
			Else {
			}
		}
	} Else {
		Set tSC=$$$OK, $ZT="Trap"
		Do {
			Use:..Connected ..Device
			Do:..Connected ..TestConnection()
			Set tWasConnected=..Connected
			If '..Connected {
				If ""=..%outIPAddr {
					If ..%PoolLimit<=1 || (..%PoolLimit>$G(^CacheTemp.EnsTCPJobs($Job,"children"))) {
						If ""=..Device {
							Set ..Device="|TCP|"_..Port
							If ..QSize>0 {
								If ""=..SSLConfig {
									Open ..Device:(:..Port:..#Mode_"A-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:..QSize:/TCPNOXY:/BINDTO=..LocalInterface):..#OpenTimeout  Set tOpenFailed='$Test
								} Else {
									Open ..Device:(:..Port:..#Mode_"A-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:..QSize:/TCPNOXY:/BINDTO=..LocalInterface:/SSL=..SSLConfig):..#OpenTimeout  Set tOpenFailed='$Test
								}
							} Else {
								If ""=..SSLConfig {
									Open ..Device:(:..Port:..#Mode_"A-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:1:/CLOSELISTEN:/TCPNOXY:/BINDTO=..LocalInterface):..#OpenTimeout  Set tOpenFailed='$Test
								} Else {
									Open ..Device:(:..Port:..#Mode_"A-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:1:/CLOSELISTEN:/TCPNOXY:/BINDTO=..LocalInterface:/SSL=..SSLConfig):..#OpenTimeout  Set tOpenFailed='$Test
								}
							}
							If tOpenFailed {
								Set tDevice=..Device, ..Device=""
								Set tSC=$$$EnsError($$$EnsErrTCPListen,..Port,..#OpenTimeout,"Open """_tDevice_""":(:"_..Port_":"""_..#Mode_"A-D"_""":"_..Terminators_":"_..#InputBufferSize_":"_..#OutputBufferSize_":"_$S(..QSize>0:..QSize,1:"1:/CLOSELISTEN")_":/TCPNOXY:"_$S(""=..SSLConfig:"",1:"/SSL="_..SSLConfig)_"):"_..#OpenTimeout)
								Quit
							}
						}
						$$$catTRACE("connwait","Waiting for connection on port "_..Port_" with timeout "_..CallInterval)
						$$$SetJobMonitor(..BusinessHost.%ConfigName,$$$SystemName_":"_$Job,$$$eMonitorConnected,".|"_$$$timeUTC)
						Use ..Device
						Read tDummy:..CallInterval Set tNewConnection=$Test
						If tNewConnection {
							Set tIPOK=##class(%IO.ServerSocket).remoteIPAllowed(..AllowedIPAddresses,.tRemote,.tSC1)
							If tIPOK { Set ..IOAddr=..Port_"<-"_tRemote_$S(""=..SSLConfig:"",1:"/SSL="_..SSLConfig), ..Connected=1 }
							Else { 
								Write *-2
								$$$LOGWARNING("Rejected connection attempt on port "_..Port_" from "_tRemote_" which was not found in AllowedIPAddresses list '"_..AllowedIPAddresses_"'"_$S($$$ISOK(tSC1):"",1:" :"_$$$StatusDisplayString(tSC1)))
							}
							Set ..%tracedLimit=0 ; reset when below pool limit
						}
					} Else { ; limit reached; don't accept new connections
						If '..%warnedLimit { 
							Set ..%warnedLimit=1
							$$$LOGWARNING("Not accepting new connections because limit of "_..%PoolLimit_" connection jobs has been reached")
						}
						ElseIf '..%tracedLimit {
							Set ..%tracedLimit=1
						}
					}
				}
				Else { ; If in connect-and-read mode
					If ..StayConnected=-1 || ..%OutDataReady {
						Set tSC=..ConnectOut(..CallInterval)
						If $$$ISERR(tSC) {
							Set tTxt=$$$StatusDisplayString(tSC)
							If tTxt'=..%warnedConnect {
								$$$LOGWARNING(tTxt)
								Set ..%warnedConnect=tTxt
							}
							Else {
								$$$catTRACE("connwait",tTxt)
							}
							Set tSC=$$$OK // timeout is not fatal at this point, but do log it
						} Else { Set ..%warnedConnect="" }
					} Else {
						$$$catTRACE("connwait","Not attempting to connect out because no output data is ready")
					}
				}
			}
			If ..Connected {
				If 'tWasConnected {
					Set tTxt="New connection"_$S(""=..%outIPAddr:" on port "_..Port_" from "_tRemote, 1:" to "_..%outIPAddr_$S(..%outIPAddr[":":"|",1:":")_..Port)
					If ..%logConnections { $$$LOGINFO(tTxt) } Else { $$$TRACE(tTxt) }
					If ""=..%outIPAddr {
						If ..JobPerConnection {
							Job ClassMethod^%apiOBJ(..%ClassName(1),"connectedJob",..BusinessHost.%ConfigName,..%PoolLimit):(:65560)
							Do ..Disconnect()
							#; don't hang around before listening again
							Set ..BusinessHost.%WaitForNextCallInterval=0
							Quit
						}
						Set:'$IsObject(..Socket) ..Socket=..SocketNewObject()
						Do ..Socket.Attach(..Device)
						Set:""'=..Terminators ..Socket.LineTerminator=..Terminators
						Set $ZT="OnConnectTrap"
						Set tSC=..BusinessHost.OnConnect(0)  If $$$ISERR(tSC) Do ..Disconnect()  Quit
						Set tSC = ..WriteLine($$$MailDomain($$$MMReady,..BusinessHost.MailDomain))
OnConnectTrap
					}
					If ""'=..BusinessHost.%LastReportedError && ("ERROR <Ens>ErrGeneral: No Connection made "=$E(..BusinessHost.%LastReportedError,1,$L("ERROR <Ens>ErrGeneral: No Connection made "))) {
						Set ..BusinessHost.%LastReportedError=""
						$$$SetHostMonitor(..BusinessHost.%ConfigName,$$$eMonitorStatus,"OK")
					}
				}
				Set $ZT="OCTrap"
				set tSC=..OnConnected()
				Set $ZT="Trap"
				Do:'..StayConnected ..Disconnect()
OCContinue
			} ElseIf ..StayConnected<0&&'..JobPerConnection {
				Set tSC=$$$ERROR($$$EnsErrGeneral,"No Connection made "_$S(""'=..%outIPAddr:"to "_..%outIPAddr_$S(..%outIPAddr[":":"|",1:":"), 1:"on port ")_..Port_" within interval "_..CallInterval)
			}
		} While 0
	} ; end Else '$zu(53)
Exit
	Use ..OldIO
	$$$ACLOSEIOLOGENTRY(tSC,"StillConnected="_..Connected,$$$NULLOREF)
	Quit tSC
Trap
	Set $ZT="ChildTrap",tSC=$$$SystemError
	If (""=..%outIPAddr) {
		$$$LOGINFO("Re-opening Port "_..Port_" to listen for incoming connections")
		Use ..OldIO
		Close ..Device
		If ..QSize>0 {
			If ""=..SSLConfig {
				Open ..Device:(:..Port:..#Mode_"A-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:..QSize:/TCPNOXY:/BINDTO=..LocalInterface):..#OpenTimeout  Set tOpenFailed='$Test
			} Else {
				Open ..Device:(:..Port:..#Mode_"A-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:..QSize:/TCPNOXY:/BINDTO=..LocalInterface:/SSL=..SSLConfig):..#OpenTimeout  Set tOpenFailed='$Test
			}
		} Else {
			If ""=..SSLConfig {
				Open ..Device:(:..Port:..#Mode_"A-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:1:/CLOSELISTEN:/TCPNOXY:/BINDTO=..LocalInterface):..#OpenTimeout  Set tOpenFailed='$Test
			} Else {
				Open ..Device:(:..Port:..#Mode_"A-D":..Terminators:..#InputBufferSize:..#OutputBufferSize:1:/CLOSELISTEN:/TCPNOXY:/BINDTO=..LocalInterface:/SSL=..SSLConfig):..#OpenTimeout  Set tOpenFailed='$Test
			}
		}
		If tOpenFailed {
			Set tDevice=..Device, ..Device=""
			Set tSC=$$$EnsError($$$EnsErrTCPListen,..Port,..#OpenTimeout,"Open """_tDevice_""":(:"_..Port_":"""_..#Mode_"A-D"_""":"_..Terminators_":"_..#InputBufferSize_":"_..#OutputBufferSize_":"_$S(..QSize>0:..QSize,1:"1:/CLOSELISTEN")_":/TCPNOXY:"_$S(""=..SSLConfig:"",1:"/SSL="_..SSLConfig)_"):"_..#OpenTimeout)
		} Else {
			Use ..Device
			Do SetIO^%NLS("RAW") ; turn off translation mode
		}
	} Else { ; If in connect-and-read mode
		Do:..IsReadError(tSC) ..Disconnect()
	}
	Goto Exit
ChildTrap
	Set $ZT="",tSC=$$$SystemError
	Goto Exit
OCTrap
	Set $ZT="Trap",tSC=$$$SystemError
	Goto OCContinue

If ..Connected && (..StayConnected>0) && ($ZH-..BusinessHost.%LastHandledTime>=..StayConnected) {
	Do ..Disconnect()
	Quit $$$OK
}
Quit ##super($$$OK)

	Set tSC=$$$OK, $ZT="Trap"
	If -1=pTimeout { Read tInStr  Set tTimedOut = 0 }
	Else { Read tInStr:pTimeout  Set tTimedOut = '$Test }
	Set tZB=$ZB
	Set $ZT=""
	If tTimedOut {
		Set ..%PartialLine=..%PartialLine_tInStr
		Quit $$$ERROR($$$EnsErrTCPTerminatedReadTimeoutExpired,pTimeout,$A(..Terminators)_$S($L(..Terminators)<2:"",1:","_$A($E(..Terminators,2))),tInStr)
	}
	Set tInStr=..%PartialLine_tInStr, ..%PartialLine=""
	Set:""=..%Table ..%Table=##class(%IO.I.TranslationDevice).GetCharEncodingTable(..Charset)
	If "RAW"'=..%Table { Set pLine=$ZCVT(tInStr,"I",..%Table) }
	Else { Set pLine = tInStr }
	Set ..%HadCR=(tZB=$C(13,10)||(tZB=$C(10)&&($C(13)=$E(pLine,$L(pLine)))))
	Set:..%HadCR&&(tZB=$C(10)) $E(pLine,$L(pLine))="" ; strip off $C(13) if it came before $C(10)
Exit
	Quit tSC
Trap
	Set $ZT="", tZE=$ZE, tSC=$$$ERROR($$$CacheError,$G(tZE))
	GoTo Exit

Set tQuitErr=1  Do {
	Set tSC=..ReadLine(.tInStr,..CallInterval,1)
	If $$$ISERR(tSC) {
		If ..IsReadError(tSC) {
			Set tSC=$$$ERROR($$$EnsErrInConnectionLost,"TCP Read Line",..IOAddr,$$$StatusDisplayString(tSC))
			Set tQuitErr=0  Do ..Disconnect()
			If ""=tInStr Set tTxt=$$$StatusText(tSC), tSC=$$$OK  If ..StayConnected<0 { $$$LOGWARNING(tTxt) } ElseIf ..%logConnections { $$$LOGINFO(tTxt) } Else { $$$sysTRACE(tTxt) }
		} ElseIf $$$StatusEquals(tSC,$$$EnsErrTCPTerminatedReadTimeoutExpired) {
			If ""=tInStr { Set tSC=$$$OK } ; no error if timed out with no data
			Else { Set tQuitErr=0 }
		}
		Quit
	}
	$$$ANEWINIOLOGENTRY($$$OK,"TCP ReadLine on :"_..IOAddr,tInStr)
	Set tSC=..BusinessHost.ProcessInput(##class(Ens.StringContainer).%New(tInStr), .tStringOut)  Quit:$$$ISERR(tSC)
	If $D(tStringOut) {
		If $IsObject(tStringOut) {
			$$$ASSERT(tStringOut.%Extends("Ens.StringContainer"))
			Set tStringOut=tStringOut.StringValue
		}
	} Else { Set tStringOut="" }
	If $$$ISERR(tSC) {
		$$$ACLOSEIOLOGENTRY(tSC,"after TCP TextLine ProcessInput error on :"_..IOAddr,tStringOut)
		Quit
	}
	If ""'=tStringOut {
		Set tSC=..WriteLine(tStringOut,1)
		Set tDisconnect = $Extract($$$MMResponseQUIT,1,3)
		If (tDisconnect	= $Extract(tStringOut,1,3)) {
			Do ..Disconnect()
		}
		If $$$ISERR(tSC) {
			If ..IsWriteError(tSC) {
				Set tSC=$$$ERROR($$$EnsErrInConnectionLost,"TCP Write Line",..IOAddr,$$$StatusDisplayString(tSC))
				Set tQuitErr=0  Do ..Disconnect()
			}
			$$$ACLOSEIOLOGENTRY(tSC,"after TCP WriteLine error on :"_..IOAddr,tStringOut)
			Quit
		}
		$$$ACLOSEIOLOGENTRY(tSC,"after TCP WriteLine on :"_..IOAddr,tStringOut)
	} Else {
		$$$ACLOSEIOLOGENTRY(tSC,"after TCP ProcessInput on :"_..IOAddr,"")
	}
} While 0
If $$$ISERR(tSC) {
	#; Never quit the listener, but drop the connection on unrecognized error
	If tQuitErr&&..Connected&&..StayConnected { $$$LOGERROR("Disconnecting due to "_$$$StatusDisplayString(tSC)) Set tSC=$$$OK  Do ..Disconnect() }
	If $$$ISERR(tSC) $$$LOGSTATUS(tSC)
}
Quit $$$OK
